# Use Python to search for scripts
import os

def find_py_files(path, max_depth=3):
    """Find .py files recursively"""
    results = []
    prefix_len = len(path) + 1

    for root, dirs, files in os.walk(path):
        if '/' * (max_depth+1).replace('/', '_') in str(root):
            continue  # Too deep

        for f in files:
            if f.endswith('.py'):
                full_path = os.path.join(root, f)
                rel_path = full_path[prefix_len:]
                results.append(rel_path)

    return results[:20]  # Limit results

